// Auto-generated zero-dependency client ZIP bundler for PhishShield Extension
// Ensures 100% reliable download across all browsers (Chrome, Brave, Edge, Firefox)
// without cross-origin blocking or "File wasn't available on site" errors.

function crc32(buffer) {
  const table = new Uint32Array(256);
  for (let i = 0; i < 256; i++) {
    let c = i;
    for (let k = 0; k < 8; k++) {
      c = (c & 1) ? (0xedb88320 ^ (c >>> 1)) : (c >>> 1);
    }
    table[i] = c >>> 0;
  }
  let crc = 0 ^ (-1);
  for (let i = 0; i < buffer.length; i++) {
    crc = (crc >>> 8) ^ table[(crc ^ buffer[i]) & 0xff];
  }
  return (crc ^ (-1)) >>> 0;
}

export function createZipBlob(fileEntries) {
  const localHeaders = [];
  const centralEntries = [];
  let offset = 0;
  const encoder = new TextEncoder();

  for (const file of fileEntries) {
    const filenameBytes = encoder.encode(file.name);
    const dataBytes = typeof file.content === 'string' ? encoder.encode(file.content) : file.content;
    const crc = crc32(dataBytes);
    const size = dataBytes.length;

    // Local file header (30 bytes + name + data)
    const localHeader = new Uint8Array(30 + filenameBytes.length + size);
    const lView = new DataView(localHeader.buffer);
    lView.setUint32(0, 0x04034b50, true); // PK\x03\x04
    lView.setUint16(4, 20, true); // version needed
    lView.setUint16(6, 0, true); // flags
    lView.setUint16(8, 0, true); // compression: 0 = STORE
    lView.setUint16(10, 0, true); // mod time
    lView.setUint16(12, 0x5521, true); // mod date (2026-10-29)
    lView.setUint32(14, crc, true); // crc32
    lView.setUint32(18, size, true); // comp size
    lView.setUint32(22, size, true); // uncomp size
    lView.setUint16(26, filenameBytes.length, true); // filename length
    lView.setUint16(28, 0, true); // extra length
    localHeader.set(filenameBytes, 30);
    localHeader.set(dataBytes, 30 + filenameBytes.length);

    localHeaders.push(localHeader);

    // Central directory entry (46 bytes + name)
    const centralEntry = new Uint8Array(46 + filenameBytes.length);
    const cView = new DataView(centralEntry.buffer);
    cView.setUint32(0, 0x02014b50, true); // PK\x01\x02
    cView.setUint16(4, 20, true); // version made by
    cView.setUint16(6, 20, true); // version needed
    cView.setUint16(8, 0, true); // flags
    cView.setUint16(10, 0, true); // compression: 0 = STORE
    cView.setUint16(12, 0x5521, true); // mod date
    cView.setUint32(16, crc, true); // crc32
    cView.setUint32(20, size, true); // comp size
    cView.setUint32(24, size, true); // uncomp size
    cView.setUint16(28, filenameBytes.length, true); // filename len
    cView.setUint16(30, 0, true); // extra len
    cView.setUint16(32, 0, true); // comment len
    cView.setUint16(34, 0, true); // disk start
    cView.setUint16(36, 0, true); // int attr
    cView.setUint32(38, 0o100644 << 16, true); // ext attr
    cView.setUint32(42, offset, true); // offset
    centralEntry.set(filenameBytes, 46);

    centralEntries.push(centralEntry);

    offset += localHeader.length;
  }

  const centralDirOffset = offset;
  let centralDirSize = 0;
  for (const ce of centralEntries) {
    centralDirSize += ce.length;
  }

  // End of central directory record (22 bytes)
  const eocd = new Uint8Array(22);
  const eView = new DataView(eocd.buffer);
  eView.setUint32(0, 0x06054b50, true); // PK\x05\x06
  eView.setUint16(4, 0, true); // disk num
  eView.setUint16(6, 0, true); // disk with central dir
  eView.setUint16(8, fileEntries.length, true); // entries on disk
  eView.setUint16(10, fileEntries.length, true); // total entries
  eView.setUint32(12, centralDirSize, true); // size of central dir
  eView.setUint32(16, centralDirOffset, true); // offset of central dir
  eView.setUint16(20, 0, true); // comment length

  const totalLength = centralDirOffset + centralDirSize + 22;
  const out = new Uint8Array(totalLength);
  let pos = 0;
  for (const lh of localHeaders) {
    out.set(lh, pos);
    pos += lh.length;
  }
  for (const ce of centralEntries) {
    out.set(ce, pos);
    pos += ce.length;
  }
  out.set(eocd, pos);

  return new Blob([out], { type: 'application/zip' });
}

